// Option B's drop list is the whole point of this ingest, so it is ASSERTED here
// rather than trusted from the extractor. A passage that still carries a dropped
// field's label means the field filter leaked and the run must not continue —
// that is how the Study Guide would quietly re-import the ~365 vital-stat sites
// and the Commercial Examples that plan 05 §2b excluded.
const raw = $input.first().json.data ?? $input.first().json;
const passages = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!Array.isArray(passages) || !passages.length) throw new Error('No passages parsed');

const EXPECTED = Number($('Doc variant').first().json.expected_count);
if (passages.length !== EXPECTED)
  throw new Error(`Expected ${EXPECTED} passages, got ${passages.length} — re-probe before ingesting`);

const ALLOWED = new Set(['History', 'Techniques']);
const BANNED = /Commercial\s+Examples:|Ingredients:|Overall\s+Impression:|Vital\s+Statistics:/;

const rows = passages.map((p, i) => {
  if (!ALLOWED.has(p.field))
    throw new Error(`Passage ${i} has field "${p.field}" — only History and Techniques are in scope`);
  const text = String(p.text ?? '').trim();
  if (text.split(/\s+/).length < 8) throw new Error(`Passage ${i} (${p.name}) is a stub`);
  if (BANNED.test(text))
    throw new Error(`Passage ${i} (${p.name}/${p.field}) contains a DROPPED field label — the filter leaked`);
  const style = `${p.code} ${p.name}`.trim();
  return { ord: i, style, field: p.field, text };
});

const byField = {};
for (const r of rows) byField[r.field] = (byField[r.field] ?? 0) + 1;
const words = rows.reduce((n, r) => n + r.text.split(/\s+/).length, 0);

return [{ json: { rows, stats: {
  passages: rows.length, history: byField.History ?? 0,
  techniques: byField.Techniques ?? 0, words,
  styles: new Set(rows.map(r => r.style)).size } } }];

const items = $input.all();
return [{ json: {
  ids:    items.map(i => i.json.id),
  inputs: items.map(i => i.json.content),
}}];

const src = $('Assemble embed input').first().json;
const emb = $json.embeddings;
if (!Array.isArray(emb) || emb.length !== src.ids.length)
  throw new Error(`Embedding count ${emb?.length} != inputs ${src.ids.length}`);
if (emb[0].length !== 1024)
  throw new Error(`Expected 1024 dims, got ${emb[0].length} — schema mismatch`);
return src.ids.map((id, i) => ({
  json: { chunk_id: id, embedding: '[' + emb[i].join(',') + ']' },
}));

const r = $json;
if (r.missing > 0) throw new Error(`${r.missing} of ${r.total} cards have no embedding — not promoted`);
if (!r.is_current) throw new Error(`Version ${r.version_id} did not become current`);
return [{ json: r }];
